const fileManager:any=(globalThis as any).FileManager
const imagePathCache=new Map<string,Promise<string>>()
;(globalThis as any).__ehentaiClearImageMemoryCache=()=>imagePathCache.clear()
const PREVIEW_WIDTH=96, PREVIEW_HEIGHT=128, IMAGE_TIMEOUT_MS=15_000, MAX_IMAGE_REQUESTS=3
type ImageStage="home-thumbnail"|"preview-thumbnail"|"reader-image"
type PendingImageTask={stage:ImageStage;sequence:number;enqueuedAt:number;start:()=>void}
const IMAGE_PRIORITY:Record<ImageStage,number>={"home-thumbnail":0,"preview-thumbnail":1,"reader-image":2}
const pendingImageTasks:PendingImageTask[]=[];let activeImageTasks=0;let imageTaskSequence=0
function drainImageTasks(){while(activeImageTasks<MAX_IMAGE_REQUESTS&&pendingImageTasks.length){pendingImageTasks.sort((a,b)=>IMAGE_PRIORITY[b.stage]-IMAGE_PRIORITY[a.stage]||a.sequence-b.sequence);pendingImageTasks.shift()?.start()}}
function enqueueImageTask<T>(stage:ImageStage,work:(queueMs:number)=>Promise<T>):Promise<T>{const enqueuedAt=Date.now();return new Promise((resolve,reject)=>{const start=()=>{activeImageTasks+=1;void work(Date.now()-enqueuedAt).then(resolve,reject).finally(()=>{activeImageTasks-=1;drainImageTasks()})};pendingImageTasks.push({stage,sequence:imageTaskSequence++,enqueuedAt,start});drainImageTasks()})}
function hashText(value:string){let hash=2166136261;for(let i=0;i<value.length;i++){hash^=value.charCodeAt(i);hash=Math.imul(hash,16777619)}return(hash>>>0).toString(16)}
function imageHost(url:string){try{return new URL(url).host}catch{return "invalid-host"}}
export function validCachedImagePayload(contentType:string,data:any){return isImagePayload(contentType,data)}
async function cachedImagePath(url:string,stage:ImageStage,options?:any,refresh=false){
  const existing=imagePathCache.get(url);if(existing)return existing
  const task=enqueueImageTask(stage,async queueMs=>{const started=Date.now();let fetchStarted=0;let response:any
    try{const dir=`${Script.directory}/.image-cache`;await fileManager.createDirectory(dir,true);const ext=new URL(url).pathname.match(/\.(jpg|jpeg|png|webp)$/i)?.[1]?.toLowerCase()||"jpg";const path=`${dir}/${hashText(url)}.${ext}`
      try{if(refresh&&await fileManager.isFile(path))await fileManager.remove(path);if(!refresh&&await fileManager.isFile(path)){await reportSafe({stage,ok:true,request:{url,status:200,statusText:"cache"},notes:`host=${imageHost(url)}; queueMs=${queueMs}; fetchMs=0; totalMs=${queueMs+Date.now()-started}; contentType=cache; settle=cache-hit`});return path}}catch{}
      fetchStarted=Date.now();response=await fetch(url,{...(options||{}),signal:AbortSignal.timeout(stage==="reader-image"?20_000:IMAGE_TIMEOUT_MS)} as any);const contentType=String(response.headers?.get?.("content-type")||"");if(!response.ok)throw new Error(`HTTP ${response.status}`);const data=await response.data();if(!validCachedImagePayload(contentType,data))throw new Error("图片响应无效。");const fetchMs=Date.now()-fetchStarted;await fileManager.writeAsData(path,data)
      await reportSafe({stage,ok:true,request:{url,status:Number(response.status||0),statusText:String(response.statusText||"")},notes:`host=${imageHost(url)}; queueMs=${queueMs}; fetchMs=${fetchMs}; totalMs=${queueMs+Date.now()-started}; contentType=${contentType||"unknown"}; settle=written`});return path
    }catch(error){imagePathCache.delete(url);await reportSafe({stage,ok:false,error,request:{url,status:Number(response?.status||0),statusText:String(response?.statusText||"")},notes:`host=${imageHost(url)}; queueMs=${queueMs}; fetchMs=${fetchStarted?Date.now()-fetchStarted:0}; totalMs=${queueMs+Date.now()-started}; settle=failed`});throw error}
  });imagePathCache.set(url,task);return task
}
function CachedThumbnail({url,stage,frame,cornerRadius}:{url:string;stage:"home-thumbnail"|"preview-thumbnail";frame:any;cornerRadius:number}){const[filePath,setFilePath]=useState("");const[error,setError]=useState("");useEffect(()=>{let cancelled=false;setFilePath("");setError("");void cachedImagePath(url,stage).then(path=>{if(!cancelled)setFilePath(path)}).catch(caught=>{if(!cancelled)setError("图片加载失败，请稍后重试")});return()=>{cancelled=true}},[url,stage]);if(error)return <Image systemName="exclamationmark.triangle" frame={frame} foregroundStyle="systemOrange"/>;if(!filePath)return <ProgressView progressViewStyle="circular" frame={frame}/>;return <Image filePath={filePath} resizable scaleToFill frame={frame} clipShape={{type:"rect",cornerRadius}}/>}
function PreviewThumbnail({page}:{page:GalleryPageLink}){const sprite=Boolean(page.thumb&&page.thumbWidth>0&&page.thumbHeight>0);if(!page.thumb)return <Image systemName="photo" frame={{width:PREVIEW_WIDTH,height:PREVIEW_HEIGHT}} foregroundStyle="secondaryLabel"/>;if(!sprite)return <CachedThumbnail url={page.thumb} stage="preview-thumbnail" frame={{width:PREVIEW_WIDTH,height:PREVIEW_HEIGHT}} cornerRadius={7}/>;return <SpritePreview page={page}/>}
function SpritePreview({page}:{page:GalleryPageLink}){const[filePath,setFilePath]=useState("");const[error,setError]=useState("");useEffect(()=>{let cancelled=false;void cachedImagePath(page.thumb,"preview-thumbnail").then(path=>{if(!cancelled)setFilePath(path)}).catch(()=>{if(!cancelled)setError("图片加载失败，请稍后重试")});return()=>{cancelled=true}},[page.thumb]);if(error)return <Image systemName="exclamationmark.triangle" frame={{width:PREVIEW_WIDTH,height:PREVIEW_HEIGHT}} foregroundStyle="systemOrange"/>;if(!filePath)return <ProgressView progressViewStyle="circular" frame={{width:PREVIEW_WIDTH,height:PREVIEW_HEIGHT}}/>;return <Canvas frame={{width:PREVIEW_WIDTH,height:PREVIEW_HEIGHT}} draw={(ctx:any,size:any)=>{ctx.fillStyle="systemGray6";ctx.fillRect(0,0,size.width,size.height);const sw=Math.max(1,page.thumbWidth),sh=Math.max(1,page.thumbHeight),scale=Math.min(size.width/sw,size.height/sh),dw=sw*scale,dh=sh*scale;ctx.drawImage({filePath},page.thumbX,page.thumbY,sw,sh,(size.width-dw)/2,(size.height-dh)/2,dw,dh)}}/>}
function CachedReaderImage({url,referer,fit="width",onLoaded,onTap}:{url:string;referer:string;fit?:ReaderPreferences["fit"];onLoaded?:()=>void;onTap?:()=>void}){const[filePath,setFilePath]=useState("");const[error,setError]=useState("");const[retry,setRetry]=useState(0);useEffect(()=>{let cancelled=false;setFilePath("");setError("");const cookie=getCookieHeader(url);void cachedImagePath(url,"reader-image",{headers:{Accept:"image/webp,image/png,image/jpeg,image/*,*/*;q=0.8",Referer:referer,...(cookie?{Cookie:cookie}:{})}},retry>0).then(path=>{if(!cancelled){setFilePath(path);onLoaded?.()}}).catch(()=>{if(!cancelled)setError("图片加载失败或超时，请稍后重试")});return()=>{cancelled=true}},[url,referer,retry]);if(error)return <VStack spacing={6}>{error?<ErrorText message={error}/>:null}<Button title="重试图片" buttonStyle="bordered" action={()=>setRetry(value=>value+1)}/></VStack>;if(!filePath)return <ProgressView title="加载图片…" progressViewStyle="circular"/>;const image=<Image filePath={filePath} resizable scaleToFit frame={fit==="screen"?{maxWidth:"infinity",height:620}:{maxWidth:"infinity"}}/>;return onTap?<Button buttonStyle="plain" action={onTap}>{image}</Button>:image}
function ContinuousReaderImage({page,preferOriginal,fit,onTap}:{page:GalleryPageLink;preferOriginal:boolean;fit:ReaderPreferences["fit"];onTap:()=>void}){const[resolved,setResolved]=useState<{url:string;referer:string}|null>(null);const[error,setError]=useState("");const[retry,setRetry]=useState(0);useEffect(()=>{let cancelled=false;setResolved(null);setError("");void resolveImagePage(page.pageUrl,retry>0).then(value=>{if(!cancelled)setResolved({url:preferOriginal&&value.originalUrl?value.originalUrl:value.imageUrl,referer:value.pageUrl})}).catch(()=>{if(!cancelled)setError("图片地址解析失败，请重试")});return()=>{cancelled=true}},[page.pageUrl,preferOriginal,retry]);return <VStack spacing={8} frame={{maxWidth:"infinity"}}><Text font="caption" foregroundStyle="secondaryLabel">第 {page.index} 页</Text>{resolved?<CachedReaderImage url={resolved.url} referer={resolved.referer} fit={fit} onTap={onTap}/>:error?<VStack spacing={6}>{error?<ErrorText message={error}/>:null}<Button title="重试本页" buttonStyle="bordered" action={()=>setRetry(value=>value+1)}/></VStack>:<ProgressView title="加载图片…" progressViewStyle="circular"/>}</VStack>}
export function GalleryRow({item}:{item:GallerySummary}){return <GlassSurface padding={10}><HStack spacing={12}>{item.thumb?<CachedThumbnail url={item.thumb} stage="home-thumbnail" frame={{width:82,height:112}} cornerRadius={9}/>:<Image systemName="photo" frame={{width:82,height:112}} foregroundStyle="secondaryLabel"/>}<VStack alignment="leading" spacing={7} frame={{maxWidth:"infinity"}}><Text font="headline" lineLimit={3}>{item.title||"未命名画廊"}</Text>{item.category?<Text font="caption" padding={{horizontal:8,vertical:3}} background="secondarySystemBackground" clipShape={{ type: "rect", cornerRadius: 7 }}>{localizeCategory(item.category)}</Text>:null}<Text font="caption" foregroundStyle="secondaryLabel" lineLimit={2}>{[item.uploader,item.pages?`${item.pages} 页`:"",item.posted].filter(Boolean).join(" · ") || "画廊信息将在详情页显示"}</Text></VStack></HStack></GlassSurface>}
export function galleryIdentity(item:Pick<GallerySummary,"id"|"gid"|"token"|"url">){return item.id||[item.gid,item.token].filter(Boolean).join(":")||item.url||""}
export function galleryGridColumnCount(sizeClass:string|null|undefined){return sizeClass==="compact"?2:3}
export function selectGallery<T>(current:T|null,next:T|null){return next}
export function GalleryCard({item,note=""}:{item:GallerySummary;note?:string}){return <GlassSurface padding={9}><VStack alignment="leading" spacing={7} frame={{maxWidth:"infinity",alignment:"leading"}}>{item.thumb?<CachedThumbnail url={item.thumb} stage="home-thumbnail" frame={{maxWidth:"infinity",height:190}} cornerRadius={10}/>:<Image systemName="photo" frame={{maxWidth:"infinity",height:190}} foregroundStyle="secondaryLabel"/>}<Text font="subheadline" fontWeight="semibold" lineLimit={3}>{item.title||"未命名画廊"}</Text>{item.category?<Text font="caption" padding={{horizontal:8,vertical:3}} background="secondarySystemBackground" clipShape={{type:"rect",cornerRadius:7}}>{localizeCategory(item.category)}</Text>:null}<Text font="caption" foregroundStyle="secondaryLabel" lineLimit={2}>{[item.uploader,item.pages?`${item.pages} 页`:"",item.posted].filter(Boolean).join(" · ")||"画廊信息将在详情页显示"}</Text>{note?<Text font="caption" foregroundStyle="systemBlue" lineLimit={2}>{note}</Text>:null}</VStack></GlassSurface>}
export function LibraryGalleryGrid({items,noteForItem}:{items:GallerySummary[];noteForItem?:(item:GallerySummary)=>string}){const[selected,setSelected]=useState<GallerySummary|null>(null);return <EnvironmentValuesReader keys={["horizontalSizeClass"]}>{environment=><LazyVGrid columns={Array.from({length:galleryGridColumnCount(environment.horizontalSizeClass)},()=>({size:{type:"flexible" as const}}))} alignment="leading" spacing={12} navigationDestination={{isPresented:Boolean(selected),onChanged:presented=>{if(!presented)setSelected(current=>selectGallery(current,null))},content:selected?<GalleryDetailView summary={selected}/>:<VStack/>}}>{items.map(item=><Button key={galleryIdentity(item)} buttonStyle="plain" action={()=>setSelected(current=>selectGallery(current,item))}><GalleryCard item={item} note={noteForItem?.(item)||""}/></Button>)}</LazyVGrid>}</EnvironmentValuesReader>}
export function GalleryGrid({items}:{items:GallerySummary[]}){return <EnvironmentValuesReader keys={["horizontalSizeClass"]}>{environment=><LazyVGrid columns={environment.horizontalSizeClass==="compact"?[{size:{type:"adaptive",min:158,max:260}}]:[{size:{type:"flexible"}},{size:{type:"flexible"}},{size:{type:"flexible"}}]} alignment="leading" spacing={12}>{items.map(item=><NavigationLink key={item.id} destination={<GalleryDetailView summary={item}/>}><GalleryRow item={item}/></NavigationLink>)}</LazyVGrid>}</EnvironmentValuesReader>}
async function reportSafe(input:Parameters<typeof reportDiagnostic>[0]){try{await reportDiagnostic(input)}catch{}}

function SearchComposer({initial}:{initial:GallerySearchState}){const[state,setState]=useState(cloneSearchState(initial)),[input,setInput]=useState(initial.keyword),[suggestions,setSuggestions]=useState(searchLocalTagSuggestions(initial.keyword)),[translationStatus,setTranslationStatus]=useState(getTagTranslationStatus()),[notice,setNotice]=useState(""),inputRef=useRef(initial.keyword);useEffect(()=>{let cancelled=false;void ensureTagTranslations().then(()=>{if(cancelled)return;setTranslationStatus(getTagTranslationStatus());setSuggestions(searchLocalTagSuggestions(inputRef.current))});return()=>{cancelled=true}},[]);const changeText=(value:string)=>{inputRef.current=value;setInput(value);setSuggestions(searchLocalTagSuggestions(value));setState(current=>composeGallerySearchState(current,value,current.selectedTags||[]))};const select=(value:{namespace:string;tag:string;translated:string})=>{const tag=createGallerySearchTag(value.namespace,value.tag,value.translated);if(!tag)return;setState(current=>composeGallerySearchState(current,inputRef.current,[...(current.selectedTags||[]),tag]));inputRef.current="";setInput("");setSuggestions([])};const remove=(tag:GallerySearchTag)=>setState(current=>removeGallerySearchTag(current,tag));const save=async()=>{try{await saveSearch(state);setNotice("已保存当前完整搜索条件。") }catch(error){setNotice(error instanceof Error?error.message:"保存搜索失败。")}};return <VStack alignment="leading" spacing={9} frame={{maxWidth:"infinity"}}><TextField title="搜索画廊" value={input} onChanged={changeText} prompt="标题、作者、中文或英文标签…" submitLabel="search"/>{state.selectedTags.length?<ScrollView axes="horizontal"><HStack spacing={7}>{state.selectedTags.map(tag=><Button key={`${tag.namespace}:${tag.tag}`} title={`${tag.display} ×`} buttonStyle="bordered" action={()=>remove(tag)}/>)}</HStack></ScrollView>:null}{suggestions.length?<VStack alignment="leading" spacing={5}>{suggestions.slice(0,8).map(item=><Button key={`${item.namespace}:${item.tag}`} title={`${item.namespace}:${item.tag} / ${item.translated}`} action={()=>select(item)}/>)}</VStack>:null}<HStack spacing={10}><NavigationLink destination={<ResultsView initial={state}/>} disabled={!state.rawQuery.trim()}><Text>搜索</Text></NavigationLink><NavigationLink destination={<HomeFilterEntry initial={state}/>}><Text>+ 高级筛选</Text></NavigationLink><Button title="保存搜索" disabled={!state.rawQuery.trim()&&!state.selectedTags.length} action={()=>void save()}/><NavigationLink destination={<QuickSearchScene/>}><Text>搜索书签</Text></NavigationLink></HStack>{notice?<Text font="caption" foregroundStyle="systemGreen">{notice}</Text>:null}{state.rawQuery?<Text font="caption" foregroundStyle="secondaryLabel">{state.rawQuery}</Text>:null}<Text font="caption" foregroundStyle={translationStatus.fullDatabaseLoaded?"secondaryLabel":"systemOrange"}>{translationStatus.fullDatabaseLoaded?`完整标签库 ${translationStatus.count} 条 · ${translationStatus.source}`:translationStatus.error?`标签库加载失败：${translationStatus.error}`:"正在加载完整标签库…"}</Text></VStack>}

export function SearchScene(){return <List navigationTitle="搜索" navigationBarTitleDisplayMode="large" background={<PageBackground/>}><Section><SearchComposer initial={createHomeSearchState()}/></Section><Section footer={<Text>标签建议来自本地翻译库；已选标签使用 E-Hentai 精确标签语法。</Text>}><NavigationLink destination={<QuickSearchScene/>}><Text>已保存的快速搜索</Text></NavigationLink></Section></List>}

function FilterView({ initial, onApply, dismissAfterApply = true }: {
  initial: GallerySearchState
  onApply: (state: GallerySearchState) => void
  dismissAfterApply?: boolean
}) {
  const dismiss = Navigation.useDismiss()
  const [excludedCategoryMask, setExcludedCategoryMask] = useState(initial.excludedCategoryMask)
  const [quick, setQuick] = useState<QuickFilterKey>(initial.quickFilter)
  const [advanced, setAdvanced] = useState(initial.advanced)
  const apply = () => {
    onApply({ ...cloneSearchState(initial), excludedCategoryMask, quickFilter: quick, advanced })
    if (dismissAfterApply) dismiss()
  }
  return <List navigationTitle="搜索筛选" navigationBarTitleDisplayMode="inline">
    <Section header={<Text textCase={null}>分类</Text>}><VStack alignment="leading" spacing={9}><Text font="caption" foregroundStyle="secondaryLabel">点按可排除分类；变暗 = 排除</Text><Button title="全部包含" buttonStyle={excludedCategoryMask===0?"borderedProminent":"bordered"} action={()=>setExcludedCategoryMask(0)}/><LazyVGrid columns={[{size:{type:"adaptive",min:96,max:160}}]} alignment="leading" spacing={8}>{GALLERY_CATEGORIES.filter(item=>item.bit).map(item=>{const excluded=(excludedCategoryMask&item.bit)!==0;return <Button key={item.key} title={item.label} buttonStyle={excluded?"bordered":"borderedProminent"} opacity={excluded?0.45:1} action={()=>setExcludedCategoryMask(mask=>toggleExcludedCategory(mask,item.bit))}/>})}</LazyVGrid></VStack></Section>
    <Section header={<Text textCase={null}>语言与常用筛选</Text>}><VStack alignment="leading" spacing={7}>{QUICK_FILTERS.map(item => <Button key={item.key} title={`${quick === item.key ? "✓ " : ""}${item.label}`} buttonStyle={quick === item.key ? "borderedProminent" : "bordered"} action={() => setQuick(item.key)} />)}</VStack></Section>
    <Section header={<Text textCase={null}>高级搜索</Text>}><Button title={advanced.enabled ? "关闭高级搜索" : "启用高级搜索"} buttonStyle={advanced.enabled ? "borderedProminent" : "bordered"} action={() => setAdvanced({ ...advanced, enabled: !advanced.enabled })} />{advanced.enabled ? <VStack alignment="leading" spacing={8}><Button title={`${advanced.searchName ? "✓" : "○"} 搜索画廊名称`} action={() => setAdvanced({ ...advanced, searchName: !advanced.searchName })} /><Button title={`${advanced.searchTags ? "✓" : "○"} 搜索画廊标签`} action={() => setAdvanced({ ...advanced, searchTags: !advanced.searchTags })} /><Button title={`${advanced.searchDescription ? "✓" : "○"} 搜索画廊描述`} action={() => setAdvanced({ ...advanced, searchDescription: !advanced.searchDescription })} /><VStack alignment="leading" spacing={8}><Text font="caption">最低评分</Text><LazyVGrid columns={[{size:{type:"adaptive",min:64,max:96}}]} alignment="leading" spacing={8}>{(["","2","3","4","5"] as const).map(value=><Button key={value||"any"} title={value?`${value}+`:"不限"} buttonStyle={advanced.minimumRating===value?"borderedProminent":"bordered"} action={()=>setAdvanced({...advanced,minimumRating:value})}/>)}</LazyVGrid></VStack><HStack spacing={8}><TextField title="最少页数" value={advanced.pageFrom} onChanged={pageFrom=>setAdvanced({...advanced,pageFrom:pageFrom.replace(/\D/g,"")})} prompt="最少" keyboardType="numberPad"/><TextField title="最多页数" value={advanced.pageTo} onChanged={pageTo=>setAdvanced({...advanced,pageTo:pageTo.replace(/\D/g,"")})} prompt="最多" keyboardType="numberPad"/></HStack><Button title={`${advanced.searchTorrents?"✓":"○"} 仅含种子`} action={()=>setAdvanced({...advanced,searchTorrents:!advanced.searchTorrents})}/><Button title={`${advanced.searchTorrentFilenames?"✓":"○"} 搜索种子文件名`} action={()=>setAdvanced({...advanced,searchTorrentFilenames:!advanced.searchTorrentFilenames})}/><Button title={`${advanced.searchLowPowerTags?"✓":"○"} 搜索低权重标签`} action={()=>setAdvanced({...advanced,searchLowPowerTags:!advanced.searchLowPowerTags})}/><Button title={`${advanced.searchDownvotedTags?"✓":"○"} 搜索被否决标签`} action={()=>setAdvanced({...advanced,searchDownvotedTags:!advanced.searchDownvotedTags})}/><Button title={`${advanced.disableLanguageFilter?"✓":"○"} 禁用默认语言过滤`} action={()=>setAdvanced({...advanced,disableLanguageFilter:!advanced.disableLanguageFilter})}/><Button title={`${advanced.disableUploaderFilter?"✓":"○"} 禁用默认上传者过滤`} action={()=>setAdvanced({...advanced,disableUploaderFilter:!advanced.disableUploaderFilter})}/><Button title={`${advanced.disableTagFilter?"✓":"○"} 禁用默认标签过滤`} action={()=>setAdvanced({...advanced,disableTagFilter:!advanced.disableTagFilter})}/><Button title={`${advanced.showExpunged?"✓":"○"} 显示已删除`} action={()=>setAdvanced({...advanced,showExpunged:!advanced.showExpunged})}/></VStack> : null}</Section>
    <Section><Button title="应用筛选" buttonStyle="borderedProminent" action={apply} /></Section>
  </List>
}

function ResultsView({ initial }: { initial: GallerySearchState }) {
  const [state, setState] = useState(cloneSearchState(initial))
  const [items, setItems] = useState<GallerySummary[]>([])
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState("")
  const [resultCount, setResultCount] = useState("")
  const [prev, setPrev] = useState("")
  const [next, setNext] = useState("")
  const requestEpoch = useRef(0)
  const load = async (direct?: string, nextState: GallerySearchState = state) => {
    const epoch = ++requestEpoch.current
    setLoading(true); setError("")
    const url = direct || buildGallerySearchUrl(getBaseUrl(), nextState)
    try {
      const page = await searchGalleries("", url)
      if (epoch !== requestEpoch.current) return
      setItems(page.items); setResultCount(page.resultCount); setPrev(page.prevHref); setNext(page.nextHref)
      await reportSafe({ stage: "gallery-search-filter", ok: true, request: { url: page.url }, notes: `items=${page.items.length}; excludedMask=${nextState.excludedCategoryMask}; tagPresent=${nextState.mode === "tag"}` })
    } catch (caught) {
      if (epoch !== requestEpoch.current) return
      setError(caught instanceof Error ? caught.message : String(caught)); setItems([]);setResultCount("");setPrev("");setNext("")
    } finally {
      if (epoch === requestEpoch.current) setLoading(false)
    }
  }
  useEffect(() => { void load(undefined, initial) }, [])
  const apply = (value: GallerySearchState) => { setState(value); setPrev(""); setNext(""); void load(undefined, value) }
  return <List navigationTitle={searchTitle(state)} navigationBarTitleDisplayMode="inline" overlay={loading && items.length === 0 ? <ProgressView title="正在搜索…" progressViewStyle="circular" /> : undefined} background={<PageBackground/>}>
    <Section><HStack><VStack alignment="leading" spacing={3}><Text font="headline">{searchTitle(state)}</Text>{searchRawQuery(state) ? <Text font="caption" foregroundStyle="secondaryLabel">{searchRawQuery(state)}</Text> : null}<Text font="caption" foregroundStyle="secondaryLabel">{categoryExclusionSummary(state.excludedCategoryMask)} · {getQuickFilter(state.quickFilter).label}</Text></VStack><Spacer /><Button title="保存搜索" action={()=>void saveSearch(state).catch(()=>{})}/><NavigationLink destination={<QuickSearchScene/>}><Text>搜索书签</Text></NavigationLink><NavigationLink destination={<FilterView initial={state} onApply={apply} />}><Text>筛选</Text></NavigationLink></HStack>{error?<ErrorText message={error}/>:null}</Section>
    <Section header={<Text textCase={null}>{[resultCount ? `结果 ${resultCount}` : "", items.length ? `本页 ${items.length} 条` : ""].filter(Boolean).join(" · ") || "搜索结果"}</Text>}><GalleryGrid items={items}/>{!loading && !error && items.length === 0 ? <EmptyState message="没有找到匹配的画廊。可调整搜索词或筛选条件后重试。" /> : null}{error ? <Button title="重试搜索" buttonStyle="bordered" action={() => { void load() }} /> : null}</Section>
    {prev || next ? <Section footer={<Text>浏览更多结果</Text>}><HStack><Button title="上一页" systemImage="chevron.left" buttonStyle="bordered" disabled={!prev || loading} action={() => { if (prev) void load(prev) }} /><Spacer /><Button title="下一页" systemImage="chevron.right" buttonStyle="bordered" disabled={!next || loading} action={() => { if (next) void load(next) }} /></HStack></Section> : null}
  </List>
}

export function ImageSearchScene(){const[items,setItems]=useState<GallerySummary[]>([]),[loading,setLoading]=useState(false),[error,setError]=useState("");const run=async(coversOnly=false)=>{setLoading(true);setError("");try{const picked=await Photos.pickPhotos(1);if(!picked.length)return;const page=await imageSearch(picked[0],{similar:true,coversOnly,showExpunged:true});setItems(page.items)}catch(e){setError(e instanceof Error?e.message:"图片搜索失败")}finally{setLoading(false)}};return <List navigationTitle="图片搜索" overlay={loading?<ProgressView title="正在上传并搜索…" progressViewStyle="circular"/>:undefined}><Section><Text font="caption" foregroundStyle="secondaryLabel">从照片中选择一张图片，使用 E-Hentai 图片搜索协议。图片仅发送到当前 E/Ex 搜索服务。</Text><HStack><Button title="相似图片搜索" buttonStyle="borderedProminent" action={()=>void run(false)}/><Button title="仅搜索封面" buttonStyle="bordered" action={()=>void run(true)}/></HStack>{error?<ErrorText message={error}/>:null}</Section><Section header={<Text textCase={null}>搜索结果 · {items.length}</Text>}>{items.map(item=><NavigationLink key={item.id} destination={<GalleryDetailView summary={item}/>}><GalleryRow item={item}/></NavigationLink>)}{!loading&&!error&&!items.length?<EmptyState message="选择图片后，结果会复用现有画廊列表和详情流程。"/>:null}</Section></List>}
