export type ReaderTapZone="left"|"right"|"centerUpper"|"centerLower"
export type ReaderTapAction="previous"|"next"|"settings"|"progress"
export function readerTapAction(zone:ReaderTapZone,direction:ReaderPreferences["direction"]):ReaderTapAction{if(zone==="centerUpper")return"settings";if(zone==="centerLower")return"progress";return zone==="left"?(direction==="rtl"?"next":"previous"):(direction==="rtl"?"previous":"next")}
export function readerTargetIndex(index:number,count:number,action:"previous"|"next"){if(count<=0)return 0;return Math.max(0,Math.min(count-1,index+(action==="next"?1:-1)))}
export function shouldScheduleAutoPage(playing:boolean,continuous:boolean,index:number,count:number){return playing&&!continuous&&index>=0&&index<count-1}
function ReaderQuickSettings({prefs,onChange}:{prefs:ReaderPreferences;onChange:(update:Partial<ReaderPreferences>)=>void}){return <List presentationDetents={["medium","large"]}><Section header={<Text textCase={null}>快速阅读设置</Text>}><Toggle title="连续纵向阅读" value={prefs.layout==="continuous"} onChanged={value=>onChange({layout:value?"continuous":"single"})}/><Toggle title="从右向左翻页" value={prefs.direction==="rtl"} onChanged={value=>onChange({direction:value?"rtl":"ltr"})}/><Toggle title="适应屏幕" value={prefs.fit==="screen"} onChanged={value=>onChange({fit:value?"screen":"width"})}/><Toggle title="优先原图" value={prefs.preferOriginal} onChanged={preferOriginal=>onChange({preferOriginal})}/><Stepper title={`相邻预加载：${prefs.preload}`} onIncrement={()=>onChange({preload:Math.min(4,prefs.preload+1)})} onDecrement={()=>onChange({preload:Math.max(0,prefs.preload-1)})}/><Stepper title={`自动翻页：${prefs.autoPageSeconds} 秒`} onIncrement={()=>onChange({autoPageSeconds:Math.min(30,prefs.autoPageSeconds+1)})} onDecrement={()=>onChange({autoPageSeconds:Math.max(2,prefs.autoPageSeconds-1)})}/></Section></List>}
function ReaderProgressOverlay({index,count,playing,onJump,onToggle}:{index:number;count:number;playing:boolean;onJump:(index:number)=>void;onToggle:()=>void}){const[value,setValue]=useState(index+1);useEffect(()=>setValue(index+1),[index]);return <GlassSurface padding={12}><VStack alignment="leading" spacing={8} frame={{maxWidth:"infinity"}}><HStack><Text font="headline">{index+1} / {count}</Text><Spacer/><Button title={playing?"暂停自动翻页":"开始自动翻页"} systemImage={playing?"pause.fill":"play.fill"} action={onToggle}/></HStack><Slider value={value} min={1} max={Math.max(1,count)} step={1} onChanged={setValue} onEditingChanged={editing=>{if(!editing)onJump(Math.round(value)-1)}} label={<Text>阅读进度</Text>}/><Button title="直接跳页" buttonStyle="bordered" action={()=>onJump(Math.round(value)-1)}/></VStack></GlassSurface>}
